import json
import math
from pathlib import Path


def _no_constant(value):
    raise ValueError(f"invalid JSON number: {value}")


def _object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def _check_finite(value):
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("non-finite JSON number")
    if isinstance(value, list):
        for item in value:
            _check_finite(item)
    elif isinstance(value, dict):
        for item in value.values():
            _check_finite(item)


def load_json_payload(path):
    try:
        value = json.loads(
            Path(path).read_text(encoding="utf-8"),
            parse_constant=_no_constant,
            object_pairs_hook=_object,
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ValueError(f"cannot load JSON payload: {error}") from error
    if not isinstance(value, (dict, list)):
        raise ValueError("JSON payload must be an object or array")
    _check_finite(value)
    return value


def safe_relative_path(value):
    if not isinstance(value, str) or not value or "\\" in value or ":" in value:
        raise ValueError("unsafe path")
    parts = value.split("/")
    if any(part in ("", ".", "..") for part in parts):
        raise ValueError("unsafe path")
    return Path(*parts)


def resolve_safe(root, value):
    relative = safe_relative_path(value)
    root = Path(root).resolve()
    resolved = (root / relative).resolve()
    try:
        resolved.relative_to(root)
    except ValueError as error:
        raise ValueError("path escapes root") from error
    return resolved


def validate_contract(contract):
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    required = ("name", "operation", "inputs", "output")
    if any(key not in contract for key in required):
        raise ValueError("missing contract field")
    for key in ("name", "operation", "output"):
        if not isinstance(contract[key], str) or not contract[key].strip():
            raise ValueError(f"invalid contract field: {key}")
    if not isinstance(contract["inputs"], list):
        raise ValueError("contract inputs must be an array")
    for item in contract["inputs"]:
        safe_relative_path(item)
    safe_relative_path(contract["output"])
    return contract


def business_input(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def numbers_equal(left, right):
    return math.isclose(left, right, rel_tol=1e-9, abs_tol=1e-9)


def require_string(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{label} must be a non-empty string")
    return value


def validate_segment_input(payload):
    if not isinstance(payload, dict):
        raise ValueError("segment input must be an object")
    for key in ("columns", "pieces", "attribute_policy"):
        if key not in payload:
            raise ValueError(f"missing field: {key}")
    columns = payload["columns"]
    pieces = payload["pieces"]
    policy = payload["attribute_policy"]
    if not isinstance(columns, list) or not isinstance(pieces, list):
        raise ValueError("columns and pieces must be arrays")
    if policy not in ("drop_conflicts", "first"):
        raise ValueError("invalid attribute_policy")
    seen_columns = []
    for column in columns:
        require_string(column, "column name")
        if column in seen_columns:
            raise ValueError("duplicate column name")
        seen_columns.append(column)

    seen_ids = set()
    seen_coordinates = []
    for piece_index, piece in enumerate(pieces):
        if not isinstance(piece, dict):
            raise ValueError("piece must be an object")
        for key in ("id", "coordinates", "data", "attrs"):
            if key not in piece:
                raise ValueError(f"missing piece field: {key}")
        piece_id = require_string(piece["id"], "piece id")
        if piece_id in seen_ids:
            raise ValueError("duplicate piece id")
        seen_ids.add(piece_id)
        coordinates = piece["coordinates"]
        data = piece["data"]
        attrs = piece["attrs"]
        if not isinstance(coordinates, list) or not isinstance(data, list):
            raise ValueError("piece coordinates and data must be arrays")
        if not isinstance(attrs, dict):
            raise ValueError("piece attrs must be an object")
        if len(coordinates) != len(data):
            raise ValueError("piece coordinate and data lengths differ")
        for coordinate in coordinates:
            if not is_number(coordinate):
                raise ValueError("coordinate must be a finite number")
            if any(numbers_equal(coordinate, old) for old in seen_coordinates):
                raise ValueError("duplicate coordinate")
            seen_coordinates.append(coordinate)
        for row in data:
            if not isinstance(row, list) or len(row) != len(columns):
                raise ValueError("data row width mismatch")
            for value in row:
                if not is_number(value):
                    raise ValueError("data value must be a finite number")
    return payload


def json_equal(left, right):
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if is_number(left) and is_number(right):
        return numbers_equal(left, right)
    if type(left) is not type(right):
        return False
    if isinstance(left, list):
        return len(left) == len(right) and all(json_equal(a, b) for a, b in zip(left, right))
    if isinstance(left, dict):
        return set(left) == set(right) and all(json_equal(left[key], right[key]) for key in left)
    return left == right

