def transform(payloads, contract):
    validate_contract(contract)
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count does not match contract inputs")
    if contract["operation"] != "segment_index":
        raise ValueError("unsupported operation")
    source = business_input(payloads[0])
    validate_segment_input(source)
    order = []
    for piece_index, piece in enumerate(source["pieces"]):
        for row, coordinate in enumerate(piece["coordinates"]):
            order.append({"coordinate": coordinate, "piece": piece["id"], "row": row})
    order.sort(key=lambda item: item["coordinate"])
    return {"name": contract["name"], "result": {"columns": source["columns"], "order": order}}

