from _common import business_input, validate_contract, validate_segment_input


def transform(payloads, contract):
    validate_contract(contract)
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count does not match contract inputs")
    if contract["operation"] != "segment_attributes":
        raise ValueError("unsupported operation")
    source = business_input(payloads[0])
    validate_segment_input(source)
    values = {}
    for piece in source["pieces"]:
        for key, value in piece["attrs"].items():
            if key not in values:
                values[key] = [value]
            else:
                values[key].append(value)
    conflicts = sorted(key for key, candidates in values.items() if any(not json_equal(candidates[0], value) for value in candidates[1:]))
    if source["attribute_policy"] == "first":
        attrs = {key: candidates[0] for key, candidates in values.items()}
    else:
        attrs = {key: candidates[0] for key, candidates in values.items() if key not in conflicts}
    return {"name": contract["name"], "result": {"attrs": attrs, "conflicts": conflicts}}

