import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _non_empty(value):
    if value is None or value is False:
        return False
    if isinstance(value, str):
        return bool(value)
    if isinstance(value, list):
        return bool(value)
    return value is not False


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core = json.loads(core_path.read_text(encoding="utf-8"), parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
    if not isinstance(core, dict) or set(core) != {"components"} or not isinstance(core["components"], dict):
        raise ValueError("invalid core object")
    components = core["components"]
    attention = []
    for name, result in components.items():
        if not isinstance(name, str) or not isinstance(result, dict):
            raise ValueError("invalid component result")
        flags = (
            result.get("blocked") is True,
            any(result.get(key) is False for key in ("complete", "checkout", "committed", "ok")),
            any(_non_empty(result.get(key)) for key in ("unavailable", "missing", "conflicts", "unreachable")),
        )
        if any(flags) and name not in attention:
            attention.append(name)
    serialized = json.dumps(core, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")
    report = {
        "title": "单变化轴的数据分片拼接",
        "component_count": len(components),
        "sha256": hashlib.sha256(serialized).hexdigest(),
        "attention": sorted(attention),
    }
    output = ROOT / "outputs" / "final_report.json"
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

