from _common import business_input, is_number, json_equal, numbers_equal, require_string, validate_contract, validate_segment_input


def _validate_index(index):
    if not isinstance(index, dict) or set(index) != {"columns", "order"}:
        raise ValueError("invalid segment_index result")
    if not isinstance(index["columns"], list) or not isinstance(index["order"], list):
        raise ValueError("invalid segment_index fields")
    for column in index["columns"]:
        require_string(column, "column name")
    if len(set(index["columns"])) != len(index["columns"]):
        raise ValueError("duplicate index column")
    for item in index["order"]:
        if not isinstance(item, dict) or set(item) != {"coordinate", "piece", "row"}:
            raise ValueError("invalid order item")
        if not is_number(item["coordinate"]):
            raise ValueError("invalid order coordinate")
        require_string(item["piece"], "order piece")
        row = item["row"]
        if not isinstance(row, int) or isinstance(row, bool) or row < 0:
            raise ValueError("invalid order row")


def _validate_attributes(attributes):
    if not isinstance(attributes, dict) or set(attributes) != {"attrs", "conflicts"}:
        raise ValueError("invalid segment_attributes result")
    if not isinstance(attributes["attrs"], dict) or not isinstance(attributes["conflicts"], list):
        raise ValueError("invalid segment_attributes fields")
    for key in attributes["conflicts"]:
        require_string(key, "attribute conflict")
    if attributes["conflicts"] != sorted(set(attributes["conflicts"])):
        raise ValueError("attribute conflicts must be unique and sorted")


def transform(payloads, contract):
    validate_contract(contract)
    if not isinstance(payloads, list) or len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count does not match contract inputs")
    if contract["operation"] != "segment_assemble":
        raise ValueError("unsupported operation")
    source = validate_segment_input(business_input(payloads[0]))
    index = business_input(payloads[1])
    attributes = business_input(payloads[2])
    _validate_index(index)
    _validate_attributes(attributes)
    if index["columns"] != source["columns"]:
        raise ValueError("index columns do not match source")

    pieces = {piece["id"]: piece for piece in source["pieces"]}
    coordinates = []
    data = []
    used = set()
    for item in index["order"]:
        piece_id = item["piece"]
        if piece_id not in pieces:
            raise ValueError("order references unknown piece")
        piece = pieces[piece_id]
        row = item["row"]
        if row >= len(piece["data"]):
            raise ValueError("order row is out of range")
        if not numbers_equal(item["coordinate"], piece["coordinates"][row]):
            raise ValueError("order coordinate does not match source")
        key = (piece_id, row)
        if key in used:
            raise ValueError("order repeats source row")
        used.add(key)
        coordinates.append(item["coordinate"])
        data.append(piece["data"][row])
    expected_count = sum(len(piece["coordinates"]) for piece in source["pieces"])
    if len(used) != expected_count:
        raise ValueError("order does not cover source")

    return {
        "name": contract["name"],
        "result": {
            "coordinates": coordinates,
            "columns": source["columns"],
            "data": data,
            "attrs": attributes["attrs"],
            "attribute_conflicts": attributes["conflicts"],
        },
    }

